    $divisors = [1];
    $factors = primeFactors($n);
    foreach ($factors as $p => $exp) {
        $currentDivisors = $divisors;
        $divisors = [];
        $power = 1;
        for ($i = 0; $i <= $exp; $i++) {
            foreach ($currentDivisors as $d) {
                $divisors[] = $d * $power;
            }
            $power *= $p;
        }
    }
    return $divisors;
}

